H("673.d.4.M",3,"Choosing a loop when a task repeats and an if statement when a choice is needed shows selecting the proper:","construct",["font","monitor","color"],"Pick the right structure.")
H("673.d.4.M",4,"A task that must run until a user types 'quit' is best handled with a:","loop",["constant","comment","single print"],"Loops repeat until a condition.")
H("673.d.4.N",3,"Combining numbers with +, -, * and / creates:","mathematical expressions",["printer jobs","network packets","screen modes"],"Operators build expressions.")
H("673.d.4.N",4,"What is the value of 2 + 3 * 4 in most languages?","14",["20","24","9"],"Multiplication occurs first.")
H("673.d.4.O",3,"A built-in function like sqrt(25) is part of a mathematics:","library",["router","cable","display"],"Libraries supply functions.")
H("673.d.4.O",4,"Calling sqrt(49) in a math library returns:","7",["49","14","24.5"],"Square root of 49 is 7.")
H("673.d.4.P",3,"Storing the value 5 in a variable named count uses:","assignment",["comparison","iteration","compilation"],"Assignment gives a variable a value.")
H("673.d.4.P",4,"In many languages, the single equals sign is used for:","assignment",["comparison only","printing","looping"],"= assigns; == compares.")
H("673.d.4.Q",3,"An algorithm that runs each step in order without choices or loops is:","sequential",["iterative","branching","recursive"],"Sequential steps run once.")
