H("673.d.5.A",3,"The legal right that lets a creator control copying of an original work is:","copyright",["trademark only","warranty","password"],"Copyright protects creative works.")
H("673.d.5.A",4,"Sharing a classmate's private chat messages without permission violates their:","privacy",["font choice","file name","screen color"],"Respect others' information.")
H("673.d.5.B",3,"Using a free-to-use image license correctly and crediting the author is the:","ethical acquisition and use of digital information",["theft of media","random copying","pirating"],"Ethical use respects creators.")
H("673.d.5.B",4,"Before using a photo from a website, an ethical user checks its:","license terms",["file color","pixel count","frame size"],"Licenses define allowed use.")
H("673.d.5.C",3,"Being polite in online posts and following school computer rules shows proper digital:","etiquette",["clutter","static","latency"],"Manners apply online.")
H("673.d.5.C",4,"Which action is a responsible use of software?","using only licensed copies",["copying and sharing paid software","cracking activation","using stolen keys"],"Respect licensing.")
H("673.d.5.D",3,"A phrase made of several words used instead of a short password is a:","pass phrase",["pop-up","menu","bookmark"],"Pass phrases are long and strong.")
H("673.d.5.D",4,"Keeping a different strong password for every account helps limit damage if one is:","stolen",["renamed","translated","printed"],"Reuse is risky.")
H("673.d.5.E",3,"Technologies like artificial intelligence raise questions about jobs, privacy and fairness, which are the social and ethical:","impacts of computing",["colors of monitors","sizes of fonts","speeds of mice"],"Advances affect society.")
H("673.d.5.E",4,"A concern about automated hiring tools is that they may produce:","biased decisions",["colorful reports","extra monitors","louder fans"],"Algorithms can reflect bias.")
H("673.d.6.A",3,"The component that holds the program being run and its data temporarily is the primary:","memory",["router","mouse","speaker"],"RAM is primary memory.")
H("673.d.6.A",4,"Which component performs calculations and logical decisions?","processor",["monitor","keyboard","speaker"],"The CPU computes.")
H("673.d.6.B",3,"Python, Java and C++ are all current:","programming languages",["file systems","web servers","network cables"],"Languages have different purposes.")
H("673.d.6.B",4,"Which language is commonly used for data science and scripting?","Python",["COBOL only","Fortran only","Pascal only"],"Python is widely used.")
H("673.d.6.C",3,"A language that is translated to machine code before running is:","compiled",["interpreted","written in HTML","a spreadsheet macro"],"Compiled languages translate first.")
H("673.d.6.C",4,"A language that executes code line by line as it reads it is:","interpreted",["compiled","assembled","burned"],"Interpreters execute directly.")
H("673.d.6.D",3,"Object-oriented design groups data and actions into:","objects",["spreadsheets","printers","cables"],"Objects bundle behavior.")
H("673.d.6.D",4,"A blueprint used to create objects in object-oriented design is a:","class",["loop","cable","constant"],"Classes define objects.")
