H("673.d.6.J",4,"Combining two conditions such as (x > 0 AND x < 10) uses a:","logical operator",["relational operator only","loop","comment"],"AND is logical.")
H("673.d.6.K",3,"The decimal number 5 in binary is:","101",["110","11","1001"],"5 = 4 + 1.")
H("673.d.6.K",4,"Text characters are stored in a computer as numbers using a coding system such as:","ASCII",["HTML","CSV","BMP"],"ASCII maps characters to numbers.")
