H("673.d.6.N",4,"A variable holding a measurement like 3.14 should be a:","real number (float)",["Boolean","string","character"],"Decimals need real types.")
H("673.d.6.O",3,"A basic value type such as an integer or character is a:","primitive",["object","class","array"],"Primitives are simple values.")
H("673.d.6.O",4,"A variable that refers to a structure with data and methods is an:","object",["integer","Boolean","constant"],"Objects have behavior.")
