H("673.d.6.P",4,"A string function that returns the number of characters in a string finds its:","length",["color","size on disk","language"],"Length counts characters.")
H("673.d.6.Q",3,"A one-dimensional array stores a list of values that are accessed by an:","index",["icon","password","cable"],"Indexes number the elements.")
H("673.d.6.Q",4,"To go through every element of an array, a programmer typically uses a:","loop",["comment","constant","single print"],"Loops traverse arrays.")
